<script lang="ts">
  import {onMount} from 'svelte';import {api} from '../lib/api.js';import type {WorkbenchState} from '../lib/workbench-state.js';import RotateCw from '@lucide/svelte/icons/rotate-cw';import Rocket from '@lucide/svelte/icons/rocket';import ExternalLink from '@lucide/svelte/icons/external-link';
  export let params:Record<string,unknown>;export let state:WorkbenchState;type Stage='understand'|'source'|'destination'|'configure'|'review'|'deploy'|'operate';const stages:Stage[]=['understand','source','destination','configure','review','deploy','operate'];
  let contextId=String(params.contextId??state.snapshot().contextId),repositoryPath=String(params.repositoryPath??'/workspace'),stage:Stage='understand',environment:'development'|'staging'|'production'='production',status='',busy=false,proposal:any,sourceSnapshot:any,review:any,items:any[]=[],selectedId='',detail:any,logs:any[]=[],poll:ReturnType<typeof setInterval>|undefined,idempotencyKey=crypto.randomUUID(),environmentText='NODE_ENV=production',secrets:Array<{key:string;value:string;vaultBindingId?:string}>=[],newSecretKey='',newSecretValue='',confirmDeploy=false,browserDiagnostics:any,domains:any,vanitySlug='',customHostname='';
  const parseVariables=()=>Object.fromEntries(environmentText.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{const index=line.indexOf('=');if(index<1)throw new Error(`Invalid environment line: ${line}`);return[line.slice(0,index).trim(),line.slice(index+1)]})),bytes=(value:ArrayBuffer|Uint8Array)=>{const source=value instanceof Uint8Array?value:new Uint8Array(value);let raw='';for(const item of source)raw+=String.fromCharCode(item);return btoa(raw)},fromBase64=(value:string)=>Uint8Array.from(atob(value),character=>character.charCodeAt(0));
  async function encrypt(publicKey:string,value:string){const key=await crypto.subtle.importKey('raw',fromBase64(publicKey),{name:'ECDH',namedCurve:'P-256'},false,[]),pair=await crypto.subtle.generateKey({name:'ECDH',namedCurve:'P-256'},true,['deriveBits']),shared=await crypto.subtle.deriveBits({name:'ECDH',public:key},pair.privateKey,256),salt=crypto.getRandomValues(new Uint8Array(16)),material=new Uint8Array(48);material.set(new Uint8Array(shared));material.set(salt,32);const digest=await crypto.subtle.digest('SHA-256',material),aes=await crypto.subtle.importKey('raw',digest,'AES-GCM',false,['encrypt']),nonce=crypto.getRandomValues(new Uint8Array(12)),ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv:nonce},aes,new TextEncoder().encode(value)),ephemeral=await crypto.subtle.exportKey('raw',pair.publicKey);return{ephemeralPublicKey:bytes(ephemeral),salt:bytes(salt),nonce:bytes(nonce),ciphertext:bytes(ciphertext)}}
  async function refresh(){busy=true;try{const value=await api<any>(`/api/deployments?contextId=${encodeURIComponent(contextId)}`);items=value.deployments??[];selectedId=selectedId||items[0]?.id||'';if(selectedId){detail=await api<any>(`/api/deployments/${encodeURIComponent(selectedId)}`);const result=await api<any>(`/api/deployments/${encodeURIComponent(selectedId)}/logs?after=-1&limit=500`);logs=result.items??[];if(!proposal||stage==='deploy'||stage==='operate')stage=detail?.plan?.status==='succeeded'?'operate':'deploy'}status=items.length?`${items.length} retained deployment${items.length===1?'':'s'}`:'No retained deployment yet.'}catch(error){status=(error as Error).message}finally{busy=false}}
  async function understand(){busy=true;try{proposal=await api('/api/deployments/interpret',{method:'POST',body:JSON.stringify({contextId,repositoryPath,environment})});stage='source';status=`Detected ${proposal.manifest?.adapter?.id??'project'} from bounded project metadata.`}catch(error){status=(error as Error).message}finally{busy=false}}
  async function snapshot(){busy=true;try{sourceSnapshot=await api('/api/deployment-sources/snapshot',{method:'POST',body:JSON.stringify({contextId,path:repositoryPath})});stage='destination';status=`Verified ${sourceSnapshot.files} files (${sourceSnapshot.digest.slice(0,22)}…).`}catch(error){status=(error as Error).message}finally{busy=false}}
  function buildReview(){if(!proposal||!sourceSnapshot)throw new Error('Interpret and snapshot the source first.');const variables=parseVariables(),secretKeys=secrets.filter(item=>item.vaultBindingId).map(item=>({key:item.key,vaultBindingId:item.vaultBindingId})),phases=proposal.manifest.phases.map((item:any)=>({...item,status:'queued'}));return{protocolVersion:'fngk.deployment.v2',name:proposal.manifest.name,repositoryPath,environment,sourceSnapshot,environmentProfile:{protocolVersion:'fngk.environment.v1',name:environment,environmentClass:environment,revision:1,variables,secretKeys,consumers:proposal.runtimeRoles.map((item:any)=>item.roleId)},manifest:{...proposal.manifest,environments:{...proposal.manifest.environments,[environment]:{variables,secretReferences:secretKeys.map(item=>item.key)}}},plan:{protocolVersion:'fngk.deployment.v2',idempotencyKey,planRevision:1,sourceDigest:sourceSnapshot.digest,environmentRevision:1,phases},runtimeRoles:proposal.runtimeRoles,schedules:proposal.schedules,storageResources:proposal.storageResources}}
  function prepareReview(){try{review=buildReview();stage='review';status='Review the exact retained plan. No deployment phase has run.'}catch(error){status=(error as Error).message}}
  function addSecret(){const key=newSecretKey.trim();if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)||!newSecretValue)throw new Error('Enter a valid secret key and value.');secrets=[...secrets.filter(item=>item.key!==key),{key,value:newSecretValue}];newSecretKey='';newSecretValue=''}
  async function bindSecrets(){const pending=secrets.filter(item=>item.value&&!item.vaultBindingId);if(!pending.length)return;const key:any=await api(`/api/deployment-secrets/key?contextId=${encodeURIComponent(contextId)}`);for(const item of pending){const secretEnvelope=await encrypt(key.credentialPublicKey,item.value),stored:any=await api('/api/deployment-secrets',{method:'POST',body:JSON.stringify({contextId,secretEnvelope,confirm:true})});item.vaultBindingId=stored.vaultBindingId;item.value=''}secrets=[...secrets]}
  async function deploy(){confirmDeploy=false;busy=true;stage='deploy';try{await bindSecrets();review=buildReview();const created:any=await api('/api/deployments',{method:'POST',body:JSON.stringify({...review,contextId,confirm:true})});selectedId=created.deployment.id;await api(`/api/deployments/${encodeURIComponent(selectedId)}/actions`,{method:'POST',body:JSON.stringify({action:'approve',planRevision:1,confirm:true})});await api(`/api/deployments/${encodeURIComponent(selectedId)}/actions`,{method:'POST',body:JSON.stringify({action:'execute',planRevision:1,confirm:true})});status='Signal accepted the deployment. It continues after this panel closes.';await refresh();startPolling()}catch(error){status=(error as Error).message}finally{busy=false}}
  function startPolling(){if(poll)clearInterval(poll);poll=setInterval(async()=>{await refresh();if(['succeeded','failed','cancelled'].includes(detail?.plan?.status)){if(poll)clearInterval(poll);poll=undefined;stage=detail.plan.status==='succeeded'?'operate':'deploy'}},1000)}
  async function action(action:'cancel'|'retry'){if(!selectedId||!detail?.plan)return;busy=true;try{await api(`/api/deployments/${encodeURIComponent(selectedId)}/actions`,{method:'POST',body:JSON.stringify({action,planRevision:detail.plan.revision,confirm:true})});if(action==='retry')await api(`/api/deployments/${encodeURIComponent(selectedId)}/actions`,{method:'POST',body:JSON.stringify({action:'execute',planRevision:detail.plan.revision,confirm:true})});await refresh();startPolling()}catch(error){status=(error as Error).message}finally{busy=false}}
  async function diagnose(){if(!selectedId)return;busy=true;try{browserDiagnostics=await api(`/api/deployments/${encodeURIComponent(selectedId)}/diagnostics`,{method:'POST',body:'{}'});status=browserDiagnostics.ok?'Browser diagnostics passed.':'Browser diagnostics found a failure.'}catch(error){status=(error as Error).message}finally{busy=false}}
  async function domainAction(action:'vanity'|'custom'|'verify'){if(!selectedId)return;busy=true;try{const method=action==='vanity'?'PUT':'POST',body=action==='vanity'?{slug:vanitySlug,confirm:true}:action==='custom'?{hostname:customHostname,confirm:true}:{confirm:true};await api(`/api/deployments/${encodeURIComponent(selectedId)}/domains/${action}`,{method,body:JSON.stringify(body)});domains=await api(`/api/deployments/${encodeURIComponent(selectedId)}/domains`);status=`Domain ${action} completed.`}catch(error){status=(error as Error).message}finally{busy=false}}
  const payload=(item:any)=>{try{return atob(String(item.body_base64??''))}catch{return ''}},openTerminal=()=>window.dispatchEvent(new CustomEvent('atlas:open-terminal',{detail:{contextId,create:true,title:`Deploy · ${proposal?.manifest?.name??'project'}`}}));$: releases=detail?.releases??[];$: events=detail?.events??[];$: publicUrl=[...events].reverse().find((item:any)=>item.detail?.url)?.detail?.url;$: phaseStatus=detail?.phases??[];onMount(()=>{void refresh();return()=>{if(poll)clearInterval(poll)}});
</script>
<section class="deployment-journey"><header><div><strong>Deployment journey</strong><span>{contextId} · {repositoryPath}</span></div><button title="Refresh retained deployment" onclick={refresh} disabled={busy}><RotateCw size={14}/></button></header><nav aria-label="Deployment stages">{#each stages as item,index}<button class:active={stage===item} class:done={stages.indexOf(stage)>index} onclick={()=>stage=item} disabled={item!=='understand'&&!proposal&&!(detail&&['deploy','operate'].includes(item))}>{index+1}<span>{item}</span></button>{/each}</nav><main>
{#if stage==='understand'}<section class="step"><p class="eyebrow">Start with the code</p><h2>What should Atlas deploy?</h2><p>Atlas reads bounded project metadata, detects the framework and runtime, then proposes one reviewable journey.</p><label>Source Device path<input bind:value={repositoryPath}/></label><label>Environment<select bind:value={environment} onchange={()=>environmentText=`NODE_ENV=${environment}`}><option>development</option><option>staging</option><option>production</option></select></label><button class="primary" onclick={understand} disabled={busy}>Understand project</button></section>
{:else if stage==='source'}<section class="step"><p class="eyebrow">Immutable source</p><h2>Verify what will move</h2><p>The Device applies ignore files, rejects links and traversal, and stores a content-addressed archive outside the project.</p><button class="primary" onclick={snapshot} disabled={busy}>Create verified snapshot</button>{#if sourceSnapshot}<article><b>{sourceSnapshot.files} files · {sourceSnapshot.bytes} bytes</b><code>{sourceSnapshot.digest}</code></article>{/if}</section>
{:else if stage==='destination'}<section class="step"><p class="eyebrow">Destination</p><h2>Run on {contextId}</h2><p>The verified snapshot becomes an immutable release under <code>{repositoryPath}/.fngk/releases</code>. Runtime ownership: {proposal?.runtimeRoles?.map((item:any)=>item.manager).join(', ')}.</p><button class="primary" onclick={()=>stage='configure'}>Configure deployment</button></section>
{:else if stage==='configure'}<section class="step"><p class="eyebrow">Configuration</p><h2>Environment and runtime</h2><label>Non-secret variables<textarea rows="5" bind:value={environmentText}></textarea><small>One KEY=value per line. Secrets use the Device vault.</small></label><div class="secret-entry"><input aria-label="Secret key" placeholder="DATABASE_URL" bind:value={newSecretKey}/><input aria-label="Secret value" type="password" placeholder="Encrypted directly to Device" bind:value={newSecretValue}/><button onclick={()=>{try{addSecret()}catch(error){status=(error as Error).message}}}>Add secret</button></div>{#each secrets as item}<article><b>{item.key}</b><span>{item.vaultBindingId?'Bound in Device vault':'Ready to encrypt on deploy'}</span><button onclick={()=>secrets=secrets.filter(value=>value!==item)}>Remove</button></article>{/each}<details><summary>Advanced roles, phases, schedules, and storage</summary><pre>{JSON.stringify({roles:proposal?.runtimeRoles,phases:proposal?.manifest?.phases,schedules:proposal?.schedules,storage:proposal?.storageResources},null,2)}</pre></details><button class="primary" onclick={prepareReview}>Review exact plan</button></section>
{:else if stage==='review'}<section class="step"><p class="eyebrow">Review</p><h2>Approve one retained plan</h2>{#each proposal?.warnings??[] as warning}<p class="warning">{warning}</p>{/each}<pre>{JSON.stringify(review,null,2)}</pre><button class="primary" onclick={()=>confirmDeploy=true}><Rocket size={14}/>Approve and deploy</button></section>
{:else if stage==='deploy'}<section class="step grow"><p class="eyebrow">Persisted execution</p><h2>{detail?.plan?.status??'Preparing deployment'}</h2><div class="timeline">{#each phaseStatus as phase}<article class:failed={phase.state==='failed'}><b>{phase.phase_id}</b><span>{phase.state} · attempt {phase.attempt}</span></article>{/each}</div><pre class="logs">{logs.map(item=>`[${item.phase_id??'phase'}:${item.stream}] ${payload(item)}`).join('\n')||'Waiting for retained phase output…'}</pre><div class="actions"><button onclick={openTerminal}>Open diagnostic terminal</button><button onclick={()=>action('cancel')} disabled={!selectedId}>Cancel safely</button>{#if detail?.plan?.status==='failed'}<button class="primary" onclick={()=>action('retry')}>Retry failed phase</button>{/if}</div></section>
{:else}<section class="step grow"><p class="eyebrow">Operate</p><h2>{detail?.deployment?.name??proposal?.manifest?.name} is {detail?.deployment?.status??'retained'}</h2><div class="summary"><article><b>Current release</b><span>{releases.at(-1)?.number??'—'}</span></article><article><b>Runtime roles</b><span>{detail?.runtimeRoles?.map((item:any)=>`${item.role_id}: ${item.observed_state}`).join(' · ')||'—'}</span></article><article><b>Public URL</b>{#if publicUrl}<a href={publicUrl} target="_blank" rel="noreferrer">{publicUrl}<ExternalLink size={12}/></a>{:else}<span>Not published yet</span>{/if}</article></div><details open><summary>Logs and evidence</summary><pre class="logs">{logs.map(item=>`[${item.phase_id??'phase'}:${item.stream}] ${payload(item)}`).join('\n')||'No retained output.'}</pre></details><details><summary>Route and domains</summary><label>Vanity slug<input bind:value={vanitySlug}/></label><button onclick={()=>domainAction('vanity')}>Reserve vanity hostname</button><label>Custom domain<input bind:value={customHostname}/></label><button onclick={()=>domainAction('custom')}>Attach custom domain</button><button onclick={()=>domainAction('verify')}>Verify DNS</button>{#if domains}<pre>{JSON.stringify(domains,null,2)}</pre>{/if}</details><details><summary>Browser observation</summary><button onclick={diagnose}>Run browser diagnostics</button>{#if browserDiagnostics}<pre>{JSON.stringify(browserDiagnostics,null,2)}</pre>{/if}{#if publicUrl}<iframe title="Deployed application" src={publicUrl}></iframe>{/if}</details><div class="actions"><button onclick={openTerminal}>Open terminal in Operations</button><button onclick={()=>window.dispatchEvent(new CustomEvent('atlas:open-database',{detail:{contextId}}))}>Inspect databases</button></div></section>{/if}
</main><footer>{busy?'Working…':status}</footer></section>
{#if confirmDeploy}<div class="atlas-dialog-backdrop"><div class="atlas-dialog" role="dialog" aria-modal="true"><h2>Approve this deployment?</h2><p>Signal retains the plan and continues on the Device if Atlas closes. Secret values are encrypted directly to the Device.</p><div><button onclick={()=>confirmDeploy=false}>Cancel</button><button class="primary" onclick={deploy}>Approve & deploy</button></div></div></div>{/if}
<style>
.deployment-journey{height:100%;min-height:0;display:flex;flex-direction:column;background:#0d1117;color:#d8e1ea}.deployment-journey>header{display:flex;align-items:center;padding:10px 12px;border-bottom:1px solid #252c35}.deployment-journey>header div{display:grid;gap:2px;flex:1}.deployment-journey>header span,.step>p,small{color:#8998a7;font-size:11px}.deployment-journey nav{display:flex;gap:6px;padding:6px;border-bottom:1px solid #252c35;overflow:auto}.deployment-journey nav button{display:flex;align-items:center;gap:5px;white-space:nowrap;background:#121820;border:1px solid #29313b;color:#8998a7;padding:6px 8px}.deployment-journey nav button.active{border-color:#6a9dce;color:#e6eef7}.deployment-journey nav button.done{color:#64c9b5}.deployment-journey main{flex:1;min-height:0;overflow:auto;padding:18px}.step{max-width:880px;margin:auto;display:grid;gap:12px}.step.grow{height:100%;grid-template-rows:auto auto auto minmax(120px,1fr) auto}.step h2{margin:0;font-size:21px}.eyebrow{text-transform:uppercase;letter-spacing:.12em;color:#67b9dd!important}.step label{display:grid;gap:5px;color:#9aa9b8;font-size:11px}.step input,.step select,.step textarea{padding:8px;background:#080b0f;border:1px solid #303844;color:#e3ebf3}.step article{display:grid;gap:3px;padding:9px;border:1px solid #28313b;background:#111720}.step article button{justify-self:end}.step pre{max-height:360px;margin:0;padding:10px;overflow:auto;background:#080b0f;border:1px solid #252c35;white-space:pre-wrap}.step .logs{max-height:none;min-height:120px}.primary{display:inline-flex;align-items:center;gap:6px;background:#29699f;color:white;border-color:#4388bf}.warning{padding:8px;border-left:3px solid #d7a84d;background:#241e12}.secret-entry{display:grid;grid-template-columns:1fr 2fr auto;gap:6px}.timeline{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:6px}.timeline article.failed{border-color:#bd5b63}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:7px}.summary a{color:#7db4e8;display:flex;gap:4px;align-items:center}.actions{display:flex;gap:7px;flex-wrap:wrap}.step details{border:1px solid #28313b;padding:9px}.step summary{cursor:pointer;font-weight:600}.step iframe{width:100%;height:360px;border:0;background:white;margin-top:8px}.deployment-journey>footer{padding:7px 10px;border-top:1px solid #252c35;color:#8f9dac;font-size:11px}@media(max-width:700px){.secret-entry{grid-template-columns:1fr}.deployment-journey main{padding:10px}}
</style>
